import 'package:hive_flutter/hive_flutter.dart';import 'package:uuid/uuid.dart';import '../../features/accounts/models.dart';import '../../features/feed/models.dart';class StudyStore{static late Box subjects,posts,settings;static const _uuid=Uuid();static Future<void>initialize()async{subjects=await Hive.openBox('subjects');posts=await Hive.openBox('posts');settings=await Hive.openBox('settings');if(subjects.isEmpty){final a=Subject.sample(id:'physics',name:'Physics',handle:'@physics_101',tint:0xFF9B8CFF);final b=Subject.sample(id:'organic',name:'Organic Chemistry',handle:'@organic.notes',tint:0xFFFF86B5);await subjects.put(a.id,a.toMap());await subjects.put(b.id,b.toMap());await posts.put('sample-physics',StudyPost.samplePhysics().toMap());await posts.put('sample-chemistry',StudyPost.sampleChemistry().toMap());}}static List<Subject>get allSubjects=>subjects.values.map((x)=>Subject.fromMap(Map<String,dynamic>.from(x))).toList();static List<StudyPost>get allPosts=>posts.values.map((x)=>StudyPost.fromMap(Map<String,dynamic>.from(x))).toList();static List<StudyPost>postsFor(String id)=>allPosts.where((p)=>p.subjectId==id).toList()..sort((a,b)=>b.createdAt.compareTo(a.createdAt));static Future<void>saveSubject(Subject s)=>subjects.put(s.id,s.toMap());static Future<void>savePost(StudyPost p)=>posts.put(p.id,p.toMap());static Future<void>deletePost(StudyPost p)=>posts.delete(p.id);static Future<void>renamePost(StudyPost p,String n)=>savePost(p.copyWith(sourceName:n));static Future<void>toggleSaved(StudyPost p)=>savePost(p.copyWith(saved:!p.saved));static Future<void>toggleMastered(StudyPost p)=>savePost(p.copyWith(mastered:!p.mastered));static Future<void>toggleLiked(StudyPost p)=>savePost(p.copyWith(liked:!p.liked));static String newId()=>_uuid.v4();}
